package br.com.equilibra.goal.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*; import java.util.UUID;
@Entity @Table(name="financial_goals") public class FinancialGoal { @Id @Column(length=36,updatable=false) private String id; @Column(name="owner_id",length=36,nullable=false,updatable=false) private String ownerId; @Column(nullable=false,length=150) private String name; @Column(length=2000) private String description; @Column(name="target_amount",precision=19,scale=2,nullable=false) private BigDecimal targetAmount; @Column(name="target_date") private LocalDate targetDate; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private FinancialGoalStatus status=FinancialGoalStatus.ACTIVE; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt; @Version private Long version; protected FinancialGoal(){} public FinancialGoal(String owner,String name,String description,BigDecimal target,LocalDate date){id=UUID.randomUUID().toString();ownerId=owner;rename(name);this.description=description;changeTarget(target);targetDate=date;} public void rename(String n){if(n==null||n.isBlank()||n.trim().length()>150)throw new IllegalArgumentException("name is invalid");name=n.trim();} public void changeTarget(BigDecimal v){if(v==null||v.signum()<=0||v.scale()>2)throw new IllegalArgumentException("targetAmount is invalid");targetAmount=v.setScale(2);} public void complete(){if(status!=FinancialGoalStatus.ACTIVE)throw new IllegalStateException("goal is not active");status=FinancialGoalStatus.COMPLETED;} public void archive(){if(status==FinancialGoalStatus.ARCHIVED)throw new IllegalStateException("goal is already archived");status=FinancialGoalStatus.ARCHIVED;} @PrePersist void create(){Instant n=Instant.now();createdAt=n;updatedAt=n;} @PreUpdate void update(){updatedAt=Instant.now();} public String getId(){return id;} public String getOwnerId(){return ownerId;} public String getName(){return name;} public String getDescription(){return description;} public BigDecimal getTargetAmount(){return targetAmount;} public LocalDate getTargetDate(){return targetDate;} public FinancialGoalStatus getStatus(){return status;} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;} }
